  const labels: Record<string, string> = { SymmetricMode_mc: 'Symmetric Mode', LoadTank_mc: 'Load tank',
    SaveExit_mc: 'Save and exit', Exit_mc: 'Exit tank creator', DeleteButton_mc: 'Delete selected',
    BringFront_mc: 'Bring to front', SendBack_mc: 'Send to back', AlignCenter_mc: 'Align to center',
    Undo_mc: 'Undo', Left_mc: 'Nudge left', Right_mc: 'Nudge right' };
  return <>
    <div className=\"creator stage-background\" data-assets={pack.mode}>
      {CREATOR_CONTROLS.controls.map(c => {
        const direction = c.name === 'Left_mc' ? -1 : c.name === 'Right_mc' ? 1 : 0;
        return <CreatorButton key={c.name} pack={pack} name={c.name} label={labels[c.name]}
