          disabled={c.name === 'Undo_mc' && "'!undo}
          onClick={() => { if (c.name === '"'SymmetricMode_mc') setChecked(v => "'!v);
            if (direction) setX(v => v + direction); record('"'controlClicks'); }}
          onHoldStart={direction ? () => { held.current = direction; record('holdStarts'); } : undefined}
          onHoldEnd={direction ? click => { held.current = 0; if (click) setX(v => v + direction);
            record('holdEnds'); report('holdClick', click); } : undefined} />;
      })}
      {CREATOR_CONTROLS.sliders.map(layout => {
        const resize = layout.name === 'Resize_mc';
        return <CreatorSlider key={layout.name} pack={pack} layout={layout}
          label={resize ? 'Part scale' : 'Part rotation'} value={resize ? scale : rotation}
          resetKey={resetKey} min={resize ? 0.5 : 0} max={resize ? 2 : 360}
          onBegin={() => { before.current = resize ? scale : rotation; record('sliderBegins'); }}
          onChange={v => { if (resize) setScale(v); else setRotation(v); record('sliderChanges'); }}
          onEnd={cancel => { if (cancel) { if (resize) setScale(before.current); else setRotation(before.current); }
            record('sliderEnds'); report('sliderCancel', cancel); }} />;
      })}
      <output className=\"sr-only\" aria-label=\"Control values\">{JSON.stringify({ checked, scale, rotation, x })}</output>
    </div>
    <div id=\"creator-component-fixture-controls\">
      <button onClick={() => setUndo(v => "'!v)}>Toggle fixture undo</button>
      <button onClick={() => { setScale(3); setResetKey({}); }}>Load fixture scale 3</button>
      <button onClick={() => { setScale(1); setRotation(0); setResetKey({}); }}>Reset fixture selection</button>
      <button onClick={() => setX(v => v + held.current * 3)}>Step fixture hold 3 frames</button>
    </div>
  </>;
}
export function showCreatorControls(pack: AssetPack, host: HTMLElement) {
  for (const name of ['"'controlClicks','holdStarts','holdEnds','sliderBegins','sliderChanges','sliderEnds']) host.dataset[name]='0';
